bool LmxxfNrBackend::initialize(ID3D12Device*d,ID3D12CommandQueue*q,const std::filesystem::path&a){shutdown();auto dll=a/L"LmxxfNrRuntime.dll";module_=LoadLibraryExW(dll.c_str(),nullptr,LOAD_LIBRARY_SEARCH_DLL_LOAD_DIR|LOAD_LIBRARY_SEARCH_DEFAULT_DIRS);if(!module_){lastError_=wm(GetLastError());return false;}auto g=reinterpret_cast<LmxxfNrGetApiFn>(GetProcAddress(module_,"LmxxfNrGetApi"));if(!g)return false;api_={};api_.struct_size=sizeof(api_);int32_t rc=g(LMXXF_NR_ABI_VERSION,&api_);if(rc==LMXXF_NR_INVALID_ARGUMENT){api_={};api_.struct_size=LMXXF_NR_API_V1_SIZE;rc=g(LMXXF_NR_ABI_VERSION,&api_);}if(rc!=LMXXF_NR_OK||!api_.QueryCapabilities||!api_.Create||!api_.Destroy||!api_.PrepareSession||!api_.PrepareFrame||!api_.RecordInputs||!api_.EnqueueHip||!api_.RecordOutputs||!api_.Retire||!api_.Drain||!api_.GetLastError)return false;capabilities_={};capabilities_.struct_size=sizeof(capabilities_);if(api_.QueryCapabilities(&capabilities_)!=LMXXF_NR_OK)return false;LmxxfNrCreateInfo ci{};ci.struct_size=sizeof(ci);ci.device=d;ci.queue=q;ci.assets_directory=a.c_str();if(api_.Create(&ci,&context_)!=LMXXF_NR_OK||!context_)return false;queue_=q;if(api_.PrepareSession(context_)!=LMXXF_NR_OK)return false;return true;}
