bool LmxxfNrBackend::prepareAndRecordInput(ID3D12GraphicsCommandList*l,ID3D12Resource*c,D3D12_RESOURCE_STATES st,uint32_t w,uint32_t h,float strength,uint64_t fid,bool reset){if(!ready()||!l||!c)return false;auto d=c->GetDesc();if(d.Format!=DXGI_FORMAT_R16G16B16A16_FLOAT||d.Width!=w||d.Height!=h)return false;if(reset&&api_.ResetHistory&&api_.ResetHistory(context_)!=LMXXF_NR_OK)return false;LmxxfNrFrameInfo i{};i.struct_size=sizeof(i);i.session_id=sessionId_;i.frame_id=fid?fid:++frameCounter_;i.list_generation=++listGeneration_;i.command_list=l;i.color_width=w;i.color_height=h;i.color=c;i.color_state=uint32_t(st);i.flags=LMXXF_NR_FRAME_FLAG_STRENGTH;i.transfer_strength=std::clamp(strength,0.0f,1.0f);i.color_strength=i.model_scale=i.pre_exposure=i.exposure_scale=1.0f;job_={};job_.struct_size=sizeof(job_);int32_t rc=api_.PrepareFrame(context_,&i,&job_);if(rc!=LMXXF_NR_OK)return fail("PrepareFrame",rc);rc=api_.RecordInputs(context_,job_.handle,l);return rc==LMXXF_NR_OK?true:fail("RecordInputs",rc);}
